script:
frappe.ui.form.on("Sales Order", {
    refresh: function(frm) {
        var isLayby = window.location.search.indexOf("layby=1") > -1;

        // After submit — show Print Layby Receipt button
        if (frm.doc.docstatus === 1) {
            frm.add_custom_button("Print Layby Receipt", function() {
                downloadLaybyReceipt(frm);
                setTimeout(function() {
                    window.close();
                }, 2500);
            }).addClass("btn-primary").css({
                "background-color": "#f59e0b",
                "color": "white",
                "font-weight": "bold",
                "font-size": "1rem",
                "padding": "8px 20px"
            });

            frm.set_intro("Layby saved! Click Print Layby Receipt to download and return to POS.", "green");
        }

        // Draft state — show Submit button prominently
            frm.set_intro("Review the order then click Submit to confirm the layby.", "blue");
        }
    },

    after_save: function(frm) {
        var isLayby = window.location.search.indexOf("layby=1") > -1;
        frm.set_intro("Order saved. Please Submit to confirm the layby.", "blue");
    }
});

function downloadLaybyReceipt(frm) {
    var items = frm.doc.items || [];
    var grand_total = frm.doc.grand_total || 0;
    var lines = [
        "=============================",
        "         LAYBY RECEIPT       ",
        "=============================",
        "Order     : " + frm.doc.name,
        "Date      : " + frm.doc.transaction_date,
        "Customer  : " + (frm.doc.customer_name || frm.doc.customer || "Walk-in"),
        "-----------------------------",
        "ITEMS:"
    ];
    items.forEach(function(i) {
        lines.push("  " + i.item_name + " x" + i.qty + "  @  " + i.rate + "  =  " + i.amount);
    });
    lines = lines.concat([
        "-----------------------------",
        "TOTAL     : " + frm.doc.currency + " " + grand_total,
        "=============================",
        "  Thank you for your Layby!  ",
        "  Please keep this receipt.  ",
        "============================="
    ]);
    var blob = new Blob([lines.join("
")], { type: "text/plain" });
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    a.href = url;
    a.download = "Layby-" + frm.doc.name + ".txt";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    frappe.show_alert({ message: "Layby receipt downloaded! Closing tab...", indicator: "green" }, 3);
}
